1	import Link from "next/link";
2	import { redirect } from "next/navigation";
3	import { Camera } from "lucide-react";
4	import { createClient } from "@/lib/supabase/server";
5	import { signItemImages, displayPath } from "@/lib/storage/signed";
6	import { Kicker } from "@/components/ui-fitcheck/kicker";
7	import { MobileNav } from "@/components/shell/mobile-nav";
8	import { ClosetGrid } from "@/components/closet/closet-grid";
9	
10	export default async function ClosetPage() {
11	  const supabase = await createClient();
12	  const {
13	    data: { user },
14	  } = await supabase.auth.getUser();
15	  if (!user) redirect("/");
16	
17	  const { data: items } = await supabase
18	    .from("items")
19	    .select("*")
20	    .eq("archived", false)
21	    .order("created_at", { ascending: false });
22	
23	  const rows = items ?? [];
24	  const signed = await signItemImages(rows.map(displayPath));
25	  const grid = rows.map((i) => ({
26	    ...i,
27	    name: i.name ?? i.subcategory ?? i.category,
28	    brand: i.brand,
29	    imageUrl: signed.get(displayPath(i)) ?? "",
30	  }));
31	
32	  return (
33	    <div className="flex min-h-dvh flex-1 flex-col">
34	      <main className="flex flex-1 flex-col gap-5 py-8">
35	        <header className="flex items-end justify-between px-6">
36	          <div>
37	            <Kicker>{grid.length} Pieces</Kicker>
38	            <h1 className="font-serif text-3xl text-foreground">The Closet</h1>
39	          </div>
40	        </header>
41	
42	        {grid.length === 0 ? (
43	          <div className="flex flex-1 flex-col items-center justify-center gap-4 px-8 text-center">
44	            <p className="text-sm text-muted-foreground">Your closet is empty.</p>
45	            <Link
46	              href="/closet/upload"
47	              className="rounded-[12px] bg-foreground px-6 py-3 text-sm font-semibold text-canvas"
48	            >
49	              Add your first piece
50	            </Link>
51	          </div>
52	        ) : (
53	          <ClosetGrid items={grid} />
54	        )}
55	      </main>
56	      {/* Design :192-194 — capture is the closet's primary action, so it gets
57	          the most prominent element on the screen: a 60px rust circle floating
58	          clear of the tab pill. It used to be the LEAST prominent thing here, a
59	          small cream `+` in the header. The camera glyph also says *how* a piece
60	          gets added. This is the screen's one rust element (DESIGN.md, the One
61	          Rust Rule) — which is why the nav's active tab is cream, not rust. */}
62	      <Link
63	        href="/closet/upload"
64	        aria-label="Add a piece"
65	        className="fixed bottom-[108px] right-[22px] z-[85] grid size-[60px] place-items-center rounded-full bg-brand text-[#1a0f09] shadow-[0_12px_28px_rgba(184,106,71,0.35),inset_0_1px_0_rgba(255,255,255,0.18)]"
66	      >
67	        <Camera size={26} strokeWidth={1.8} />
68	      </Link>
69	      <MobileNav />
70	    </div>
71	  );
72	}
